from itertools import product
F=['010101','110101','000101','111101','000001']
pts=[(i+1,j+1,int(F[i][j])) for i in range(5) for j in range(6)]
# Find simple modular class (i*j) mod m; subset residues classify.
for op in ['prod','sum','xor','i+j','i-j']:
  for m in range(2,16):
    vals={}
    ok=True
    for i,j,y in pts:
      x={'prod':i*j,'sum':i+j,'xor':i^j,'i+j':i+j,'i-j':i-j}[op]%m
      if x in vals and vals[x]!=y:ok=False;break
      vals[x]=y
    if ok: print(op,m,vals)

